head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.strCbd_SEL_STAT_CD = "1^상장일,2^상장폐지일";
scwin.clickIsurCd = "";
scwin.clickActDD = "";
scwin.clickComNm = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const sbmOptions = {
            id : "sbm_dts_Item",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_Item=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        dts_Item.insertRow();
        const sbmOptions2 = {
            id : "sbm_dts_Item02",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_Item02=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        dts_Item02.insertRow();
        txb_ISUR_CD02.hide();
        $c.cm.PanelToGroupBox(panel_Top);
        $c.cm.PanelToGroupBox(panel_Item01);
        $c.cm.PanelToGroupBox(panel_Item02);
        let vCurDate = $c.ut.cGetToday("yyyymmdd");
        // var vCurMonth = cGetMinusMonth(vCurDate.substring(0,4), vCurDate.substring(4,6), vCurDate.substring(6,8), 2);
        const vCurMonth = "19000101";
        edt_BzSDate.setValue(vCurMonth);
        edt_BzEDate.setValue(vCurDate);
        scwin.setCode();
        // fn_Search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41520.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

