/**
 * @method
 * @name grd_List_OnClick
 * @description grd_List 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_OnClick = function(row, colid) {
    try {
        txb_ISUR_CD02.setValue(dts_List.getCellData(row, "ISUR_CD"));
        edt_RSN_OCCR_DD.setValue(dts_List.getCellData(row, "RSN_OCCR_DD"));
        txb_ACNTG_CORP_NM.setValue(dts_List.getCellData(row, "ACNTG_CORP_NM"));
        txa_UNQFACT.text = dts_List.getCellData(row, "UNQFACT");
        edt_ACT_DD.setValue(dts_List.getCellData(row, "ACT_DD"));
        txa_REMK.text = dts_List.getCellData(row, "REMK");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41520.grd_List_OnClick" });
    }
};

/**
