///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&method=searchSfcActRsltList";
    url += "&inputMessageId=SFC_ACT_RSLT_LIST_INPUT_OUT";
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    url += "&LIST_STAT_CD=" + rdo_LIST_STAT_CD.getValue();
    url += "&SEL_STAT_CD=" + cmb_SEL_STAT_CD.getValue();
    url += "&LIST_BZ_PROCS_STA=" + edt_BzSDate.getValue();
    url += "&LIST_BZ_PROCS_END=" + edt_BzEDate.getValue();
    url += "&PROCS_STAT_CD=" + rdo_PROCS_STAT_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/RepMajagnt.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    scwin.setSpaceValue();
};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function() {
    scwin.setDataItem();
    if (txb_ISUR_CD02.getValue() === "") {
        await $c.win.alert("수정할 종목을 선택하세요.");
        return;
    }
    if (edt_RSN_OCCR_DD.getValue() === "") {
        await $c.win.alert("실질심사 내용이 없습니다.");
        return;
    }
    if (txb_ACNTG_CORP_NM.getValue() === "") {
        await $c.win.alert("수정할 내용을 입력하세요.");
        return;
    }
    trs_Save.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/RepMajagnt.do",
        ref : "dts_Item",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name trs02
 * @description trs02 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs02 = async function() {
    scwin.setDataItem();
    if (txb_ISUR_CD02.getValue() === "") {
        await $c.win.alert("수정할 종목을 선택하세요.");
        return;
    }
    if (edt_ACT_DD.getValue() === "") {
        await $c.win.alert("증선위 조치사항이 없습니다.");
        return;
    }
    if (txa_REMK.getValue() === "") {
        await $c.win.alert("수정할 내용을 입력하세요.");
        return;
    }
    trs_Save02.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Save02",
        action : "/RepMajagnt.do",
        ref : "dts_Item02",
        target : "trs_Save02=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    cmb_SEL_STAT_CD.CBData = scwin.strCbd_SEL_STAT_CD;
    cmb_SEL_STAT_CD.setSelectedIndex(0);
};

/**
 * @method
 * @name setSpaceValue
 * @description set Space Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.setSpaceValue = function() {
    edt_RSN_OCCR_DD.setValue("");
    txb_ACNTG_CORP_NM.setValue("");
    txa_UNQFACT.text = "";
    edt_ACT_DD.setValue("");
    txa_REMK.text = "";
};

/**
 * @method
 * @name setContnId
 * @description set Contn Id 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    if (Number(obj) > 0) {
        // 그리드에서 선택시
        scwin.clickIsurCd = dts_List.getCellData(Number(obj), "ISUR_CD");
        scwin.clickActDD = dts_List.getCellData(Number(obj), "ACT_DD");
        scwin.clickComNm = dts_List.getCellData(Number(obj), "COM_ABBRV");
    } else {
        scwin.clickIsurCd = "";
        scwin.clickActDD = "";
        scwin.clickComNm = "";
    }
};

/**
 * @method
 * @name openDetail
 * @description open Detail 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetail = async function(row) {
    scwin.setContnId(row);
    if (row < 0) {
        // 그리드에서 선택시
        scwin.clickIsurCd = "";
        scwin.clickActDD = "";
    }
    const hight = "740";
    const pageNM = "ULDSTF41521";
    const options = {
        id: "" + pageNM + "",
        title: "증선위조치결과 입력",
        type: "browserPopup",
        width: "1050px",
        height: hight,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/lstmgt/" + pageNM + ".gfm", options);
};

/**
 * @method
 * @name excelDown
 * @description excel Down 처리
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    $c.data.downloadGridViewExcel(grd_List, {fileName: "기업 현황", type: "2"}); //

};

/**
 * @method
 * @name setDataItem
 * @description set Data Item 처리
 * @returns {void}
 * @hidden N
 */
scwin.setDataItem = function() {
    LastJob = '수정';
    dts_Item.setCellData(1, "ISUR_CD", txb_ISUR_CD02.getValue());
    dts_Item.setCellData(1, "RSN_OCCR_DD", edt_RSN_OCCR_DD.getValue());
    dts_Item.setCellData(1, "ACNTG_CORP_NM", txb_ACNTG_CORP_NM.getValue());
    dts_Item.setCellData(1, "UNQFACT", txa_UNQFACT.getValue());
    dts_Item02.setCellData(1, "ISUR_CD", txb_ISUR_CD02.getValue());
    dts_Item02.setCellData(1, "ACT_DD", edt_ACT_DD.getValue());
    dts_Item02.setCellData(1, "REMK", txa_REMK.getValue());
};
